-- Resources content for Bookings' slice 2b, labor classes and pools as data
-- (CLAUDE.md, "Resources stay in step with the code"). Content only; the
-- schema is 20261005160000_bookings_labor_and_pools.sql. The two existing
-- guides are rewritten where the screens changed; the release note names
-- what a user notices.

select private.rc_release_guide(
  p_slug => 'bookings-rate-model',
  p_tool_key => 'bookings',
  p_title => 'The rate model',
  p_summary => 'Labor classes and their pay figures, budget lines, resource pools, service packages, the rate card a partner sees, and adopting a version.',
  p_screen_keys => array['bookings.rates'],
  p_sort_order => 10,
  p_version_note => 'Labor classes and pools as data',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Rates","marks":[{"type":"bold"}]},{"type":"text","text":" tab holds the production rate model: what each class of labor costs an hour, what a studio half-day, an event webcast, a field day or an editing hour costs WUWF, and the rates on the card a partner sees. Everything on the card is computed from the figures; nothing is typed in by hand."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Setup: labor classes and pools"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Setup","marks":[{"type":"bold"}]},{"type":"text","text":" lists the two things the model is built from. A "},{"type":"text","text":"labor class","marks":[{"type":"bold"}]},{"type":"text","text":" is a kind of production staff — the production lead, student and OPS crew, later a second producer or an engineer — paid by salary or by the hour, and either charged in a strategic price (students) or baseline-funded (professionals)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"pool","marks":[{"type":"bold"}]},{"type":"text","text":" is something that can be booked — studio, field package, live package, edit suite, webcast operations — with its unit and how it is costed: a share of the shared production pool, or its own budget lines. Finance or the Director of Operations adds a class or a pool here; nothing is deleted, only retired."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new class needs its pay figures on each draft version (the "},{"type":"text","text":"Labor","marks":[{"type":"bold"}]},{"type":"text","text":" tab), and a new pool its figures on each draft version (the "},{"type":"text","text":"Resource pools","marks":[{"type":"bold"}]},{"type":"text","text":" tab) and a resource on the term plan."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Versions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The version picker at the top switches between versions. One version is "},{"type":"text","text":"in use","marks":[{"type":"bold"}]},{"type":"text","text":" for estimates at a time. A version that has not been adopted is labelled provisional, and so is every figure from it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An adopted version never changes. To correct it, Finance selects "},{"type":"text","text":"New version","marks":[{"type":"bold"}]},{"type":"text","text":", which copies the chosen version's figures and packages into a draft."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Assumptions, labor and resource pools"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assumptions","marks":[{"type":"bold"}]},{"type":"text","text":" holds the budget lines — the shared production pool's, and the webcasting pool's own — and the two working inputs the math reads directly: the external margin and the university assessment."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Labor","marks":[{"type":"bold"}]},{"type":"text","text":" holds each class's pay figures on this version: salary and paid hours or hourly wage, the fringe or payroll load, and the external planning rate. The loaded hourly cost is recomputed from them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource pools","marks":[{"type":"bold"}]},{"type":"text","text":" holds each pool's share of the shared pool (or its own lines) and its available units a year. Cost per unit is the pool's annual cost divided by its units."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every row names who must validate it and what that takes. Finance selects "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" to change a figure on a draft, and "},{"type":"text","text":"Validated","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Accept as is","marks":[{"type":"bold"}]},{"type":"text","text":" to resolve it. "},{"type":"text","text":"What moves the price most","marks":[{"type":"bold"}]},{"type":"text","text":" re-runs the model with one figure moved."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Service packages and the rate card"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"service package","marks":[{"type":"bold"}]},{"type":"text","text":" states its hours per labor class and its units per pool, plus the external market floor. Strategic cost is resource units plus the hours of every class charged in a strategic price; incremental cost adds the other classes' hours at their loaded rate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every rate rounds up to the next $25. The external rate is the higher of the incremental cost grossed up for the margin and the assessment, and the package's market floor. The card lists one labor line per class."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record for estimates","marks":[{"type":"bold"}]},{"type":"text","text":" saves the card as computed, so an estimate priced later keeps the rate it was priced at. "},{"type":"text","text":"Print","marks":[{"type":"bold"}]},{"type":"text","text":" prints the card alone."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Adopting a version"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Finance resolves every assumption, labor figure and pool, then selects "},{"type":"text","text":"Submit for validation","marks":[{"type":"bold"}]},{"type":"text","text":". A version with anything still pending cannot be submitted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Executive Director selects "},{"type":"text","text":"Adopt","marks":[{"type":"bold"}]},{"type":"text","text":", recording the Budget/Controller's destination index for recoveries. The previous adopted version is superseded, and the new one is in use."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Change log","marks":[{"type":"bold"}]},{"type":"text","text":" lists who changed what on each version."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'bookings-calendar',
  p_tool_key => 'bookings',
  p_title => 'The calendar and the term plan',
  p_summary => 'The term plan''s two envelopes, capacity per labor class, each pool''s units and windows, blackouts and holds, bookings, and the booking rule.',
  p_screen_keys => array['bookings.calendar'],
  p_sort_order => 30,
  p_version_note => 'Capacity per labor class',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Calendar","marks":[{"type":"bold"}]},{"type":"text","text":" tab shows one term of production work: what WUWF has kept for itself, what partners have booked, and how much of each labor class's capacity is left. Capacity is measured in hours; a professional's project day is eight."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The term plan"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Director of Operations creates a term plan from "},{"type":"text","text":"Term plan","marks":[{"type":"bold"}]},{"type":"text","text":": the term's dates, the reserve share kept for strategic work, and the airtime minutes a week the station contributes. One plan is active at a time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capacity by labor class","marks":[{"type":"bold"}]},{"type":"text","text":" is where each class the term tracks gets its net hours for the term, how many people, and each person's hours a day. Two engineers at eight hours a day give the engineering class a sixteen-hour day. A class with no row is not capacity-checked."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each pool has its units for the term, how many bookings it takes in one window (two field kits take two), and the windows a booking may take. Select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" on a row to change it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The two envelopes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Production capacity","marks":[{"type":"bold"}]},{"type":"text","text":" shows, for each class, net capacity, the reserve left for strategic work, what is held and booked, and open capacity: net minus the reserve, minus holds, minus incremental and external bookings. Open the month table to see how it is spread across the term."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Airtime envelope","marks":[{"type":"bold"}]},{"type":"text","text":" is read from On Air's clocks: the avails marked as admitting a university announcement, the minutes the station already pins there, the contributed envelope from the term plan, and what is left for Traffic to sell. Airtime is placed in Traffic or On Air, never here."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Blackouts, holds and bookings"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"blackout","marks":[{"type":"bold"}]},{"type":"text","text":" closes dates to partner work on some or every pool, with a reason. A "},{"type":"text","text":"hold","marks":[{"type":"bold"}]},{"type":"text","text":" is WUWF's own use of one window, core work or maintenance, with the hours it takes from each class. The director adds both with "},{"type":"text","text":"+ Blackout","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"+ Hold","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"booking","marks":[{"type":"bold"}]},{"type":"text","text":" is a partner's hold on one window, with its hours per class. Production staff or the director adds one with "},{"type":"text","text":"+ Booking","marks":[{"type":"bold"}]},{"type":"text","text":". A tentative booking holds the window for 14 days and counts as taken; confirm it or release it from the list under the calendar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find a slot","marks":[{"type":"bold"}]},{"type":"text","text":" runs the booking rule for a window without booking it, and names the nearest open windows when the one asked for is not available."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The booking rule"}]},{"type":"paragraph","content":[{"type":"text","text":"Every booking is checked in this order: the date is not blacked out or held for WUWF; the window has a free unit on the pool, with tentative bookings counted as taken; each class's day has room for its hours; and each class has capacity for the pricing. A strategic booking draws the class's reserve; an incremental or external one draws its open capacity. A booking that would take more than half of a month's remaining open hours warns but is not refused. Only the Executive Director can record an exception, and each one is written to the audit log."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-05-bookings-labor-and-pools',
  p_tool_key => 'bookings',
  p_released_on => '2026-10-05',
  p_title => 'Bookings: labor classes and pools you can add to',
  p_guide_slugs => array['bookings-rate-model', 'bookings-calendar'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The rate model and the calendar no longer assume one professional and four fixed pools. A new Setup view under Rates lists the labor classes (the production lead and student or OPS crew today) and the resource pools (studio, field, live, edit and webcast operations), and Finance or the Director of Operations can add to either without a code change. A new Labor view holds each class's pay figures per version; service packages state hours per class and units per pool; the rate card lists one labor line per class. The term plan now tracks capacity per labor class, with headcount and hours a day, so a second producer or an engineer fits the model, and a pool can take more than one booking in a window. Every figure on the v0.1 card is unchanged. The production role is now called production staff."}]}]}$body$
);
